/* returns a suitable return code based on action state
 * rgerhards, 2009-05-07
 */
static rsRetVal getReturnCode(action_t *const pThis, wti_t *const pWti) {
    DEFiRet;

    switch (getActionState(pWti, pThis)) {
        case ACT_STATE_RDY:
            iRet = RS_RET_OK;
            break;
        case ACT_STATE_ITX:
            if (pWti->actWrkrInfo[pThis->iActionNbr].bHadAutoCommit) {
                pWti->actWrkrInfo[pThis->iActionNbr].bHadAutoCommit = 0; /* auto-reset */
                iRet = RS_RET_PREVIOUS_COMMITTED;
            } else {
                iRet = RS_RET_DEFER_COMMIT;
            }
            break;
        case ACT_STATE_RTRY:
            iRet = RS_RET_SUSPENDED;
            break;
        case ACT_STATE_SUSP:
            iRet = RS_RET_ACTION_FAILED;
            break;
        case ACT_STATE_DATAFAIL:
            iRet = RS_RET_DATAFAIL;
            break;
        case ACT_STATE_DISABLED:
            iRet = RS_RET_DISABLE_ACTION;
            break;
        default:
            DBGPRINTF("Invalid action engine state %u, program error\n", getActionState(pWti, pThis));
            iRet = RS_RET_ERR;
            break;
    }

    RETiRet;
}


/* set the action to a new state
 * rgerhards, 2007-08-02
 */
static void actionSetState(action_t *const pThis, const char *const callerName, wti_t *const pWti, uint8_t newState) {
    setActionState(pWti, pThis, newState);
    DBGPRINTF("action[%s] transitioned to state: %s (caller %s)\n", pThis->pszName, getActStateName(pThis, pWti),
              callerName);
}

static void actionDisableForWorker(action_t *const pThis, wti_t *const pWti) {
    actionDisable(pThis);
    if (pWti != NULL && getActionState(pWti, pThis) != ACT_STATE_DISABLED) {
        actionSetState(pThis, __func__, pWti, ACT_STATE_DISABLED);
    }
}

