static rsRetVal ATTR_NONNULL() actionCheckOutputRatelimit(action_t *const pAction, wti_t *const pWti) {
    unsigned int wait_usec;
    unsigned int sleep_usec;
    ratelimit_output_mode_t mode;
    DEFiRet;

    if (pAction->ratelimiter == NULL) FINALIZE;

    mode = ratelimitGetOutputMode(pAction->ratelimiter);
    if (mode == RATELIMIT_OUTPUT_MODE_DROP) {
        iRet = ratelimitMsgCount(pAction->ratelimiter, NO_TIME_PROVIDED, (char *)pAction->pszName);
        if (iRet == RS_RET_OK) {
            STATSCOUNTER_INC(pAction->ctrRateLimitAllowed, pAction->mutCtrRateLimitAllowed);
        } else if (iRet == RS_RET_DISCARDMSG) {
            STATSCOUNTER_INC(pAction->ctrRateLimitDropped, pAction->mutCtrRateLimitDropped);
        }
        FINALIZE;
    }

    for (;;) {
        wait_usec = 0;
        iRet = ratelimitMsgCountWait(pAction->ratelimiter, NO_TIME_PROVIDED, (char *)pAction->pszName, &wait_usec);
        if (iRet == RS_RET_OK) {
            STATSCOUNTER_INC(pAction->ctrRateLimitAllowed, pAction->mutCtrRateLimitAllowed);
            FINALIZE;
        }
        if (iRet != RS_RET_DISCARDMSG) FINALIZE;
        if (wtiIsShutdownImmediate(pWti)) {
            ABORT_FINALIZE(RS_RET_FORCE_TERM);
        }
        sleep_usec = wait_usec > 1000000U ? 1000000U : wait_usec;
        STATSCOUNTER_INC(pAction->ctrRateLimitPaced, pAction->mutCtrRateLimitPaced);
        STATSCOUNTER_ADD(pAction->ctrRateLimitPacedUsec, pAction->mutCtrRateLimitPacedUsec, sleep_usec);
        srSleep(sleep_usec / 1000000U, sleep_usec % 1000000U);
    }

finalize_it:
    RETiRet;
}

/* set action state according to external state file (if configured)
 */
static rsRetVal ATTR_NONNULL() checkExternalStateFile(action_t *const pThis, wti_t *const pWti) {
    char filebuf[1024];
    int fd = -1;
    int r;
    DEFiRet;

    DBGPRINTF("checking external state file\n");

    if (pThis->pszExternalStateFile == NULL) {
        FINALIZE;
    }

    fd = open(pThis->pszExternalStateFile, O_RDONLY | O_CLOEXEC);
    if (fd == -1) {
        dbgprintf("could not read external state file\n");
        FINALIZE;
    }

    r = read(fd, filebuf, sizeof(filebuf) - 1);
    if (r < 1) {
        dbgprintf("checkExternalStateFile read() returned %d\n", r);
        FINALIZE;
    }

    filebuf[r] = '\0';
    dbgprintf("external state file content: '%s'\n", filebuf);
    /* trim trailing whitespace */
    for (int j = r - 1; j > 0; --j) {
        if (filebuf[j] == '\n' || filebuf[j] == '\t' || filebuf[j] == ' ') {
            filebuf[j] = '\0';

     * message states.
     */
    if (wrkrInfo->p.tx.currIParam == 1) {
        needfree_iparams = 0;
        iparams = wrkrInfo->p.tx.iparams;
        nMsgs = wrkrInfo->p.tx.currIParam;
        if (iRet == RS_RET_DATAFAIL) {
            FINALIZE;
        } else if (iRet == RS_RET_SUSPENDED) {
            sleepBeforeRetry = 1;
        }
    } else {
        DBGPRINTF(
            "actionCommit[%s]: somewhat unhappy, full batch of %d msgs returned "
            "status %d. Trying messages as individual actions.\n",
            pThis->pszName, wrkrInfo->p.tx.currIParam, iRet);
        CHKmalloc(iparams = malloc(sizeof(actWrkrIParams_t) * pThis->iNumTpls * wrkrInfo->p.tx.currIParam));
        needfree_iparams = 1;
        int splitSuspendedSlept = 1;
        CHKiRet(actionTryRemoveHardErrorsFromBatch(pThis, pWti, iparams, &nMsgs, &splitSuspendedSlept));
        if (nMsgs > 0) {
            sleepBeforeRetry = !splitSuspendedSlept;
        }
    }

    if (nMsgs == 0) {
        ABORT_FINALIZE(RS_RET_OK);  // here, we consider everyting OK
    }

    /* We still have some messages with suspend error. So now let's do our
     * "regular" retry and suspend processing.
     */
    DBGPRINTF("actionCommit[%s]: unhappy, we still have %d uncommitted messages.\n", pThis->pszName, nMsgs);
    int bDone = 0;
    do {
        if (wtiIsShutdownImmediate(pWti)) {
            ABORT_FINALIZE(RS_RET_FORCE_TERM);
        }
        if (sleepBeforeRetry) {
            CHKiRet(actionSleepBeforeRetryingTransaction(pThis, pWti));
            sleepBeforeRetry = 0;
        }
        iRet = actionTryCommit(pThis, pWti, iparams, nMsgs);
        DBGPRINTF("actionCommit[%s]: in retry loop, iRet %d\n", pThis->pszName, iRet);
        if (iRet == RS_RET_FORCE_TERM) {
            ABORT_FINALIZE(RS_RET_FORCE_TERM);
        } else if (iRet == RS_RET_SUSPENDED) {
            int retrySlept = 0;
            iRet = actionDoRetryInternal(pThis, pWti, &retrySlept, 1, NULL);
            DBGPRINTF("actionCommit[%s]: actionDoRetry returned %d\n", pThis->pszName, iRet);
            if (iRet == RS_RET_FORCE_TERM) {
                ABORT_FINALIZE(RS_RET_FORCE_TERM);
            } else if (iRet != RS_RET_OK) {
                actionWriteErrorFile(pThis, iRet, iparams, nMsgs);
                bDone = 1;
            } else {
                sleepBeforeRetry = !retrySlept;
            }
            continue;
        } else if (iRet == RS_RET_OK || iRet == RS_RET_SUSPENDED || iRet == RS_RET_ACTION_FAILED ||
                   iRet == RS_RET_DISABLE_ACTION) {
            bDone = 1;
        }
        if (getActionState(pWti, pThis) == ACT_STATE_RDY || getActionState(pWti, pThis) == ACT_STATE_SUSP ||
            getActionState(pWti, pThis) == ACT_STATE_DISABLED || actionIsDisabled(pThis)) {
            bDone = 1;
        }
    } while (!bDone);
finalize_it:
    DBGPRINTF("actionCommit[%s]: done, iRet %d\n", pThis->pszName, iRet);
    if (needfree_iparams) {
        free(iparams);
    }
    wrkrInfo->p.tx.currIParam = 0; /* reset to beginning */
    RETiRet;
}

